import net from 'node:net';import fs from 'node:fs';import path from 'node:path';import {spawn} from 'node:child_process';import {once} from 'node:events';
const [side,entryArg,outArg]=process.argv.slice(2);if(!['ts','rust'].includes(side)||!entryArg||!outArg)throw Error('usage: node sidecar-formal.mjs ts|rust ENTRY NEW_OUT_DIR');const out=path.resolve(outArg);if(fs.existsSync(out))throw Error('output must be new');fs.mkdirSync(out,{recursive:true});const home=path.join(out,'home');fs.mkdirSync(home);const entry=path.resolve(entryArg);
const reserve=net.createServer();reserve.listen(0,'127.0.0.1');await once(reserve,'listening');const port=reserve.address().port;await new Promise(r=>reserve.close(r));
const child=spawn(side==='ts'?process.execPath:entry,side==='ts'?[entry]:[],{cwd:home,env:{PATH:process.env.PATH,HOME:home,PILOT_HOME:home,PILOTDECK_AGENT_LOOP_TCP_HOST:'127.0.0.1',PILOTDECK_AGENT_LOOP_TCP_PORT:String(port)},stdio:['ignore','pipe','pipe']});let stderr='';child.stderr.on('data',c=>stderr+=c);const raw=[];
let socket;for(let i=0;i<100;i++){socket=net.createConnection({host:'127.0.0.1',port});try{await once(socket,'connect');break}catch{socket.destroy();await new Promise(r=>setTimeout(r,20));}}
let buffer='',queue=[],waiter;socket.setEncoding('utf8');socket.on('data',c=>{buffer+=c;let i;while((i=buffer.indexOf('\n'))>=0){const m=JSON.parse(buffer.slice(0,i));buffer=buffer.slice(i+1);raw.push(m);if(waiter){let f=waiter;waiter=null;f(m)}else queue.push(m)}});const read=()=>queue.length?Promise.resolve(queue.shift()):Promise.race([new Promise(r=>waiter=r),new Promise((_,reject)=>setTimeout(()=>reject(Error('timeout')),5000))]);const send=m=>{raw.push({probeSent:m});socket.write(JSON.stringify(m)+'\n');};
try{send({kind:'request',messageId:'hello',method:'hello',payload:{}});await read();send({kind:'request',messageId:'execute',method:'execute',runId:'r',operationId:'o',requestId:'req',sessionId:'s',turnId:'t',payload:{agent:{provider:'mock',model:'test'},tools:[{name:'owned_tool',description:'fixture',concurrencySafe:true,inputSchema:{type:'object',properties:{}}},{name:'serial_tool',description:'serial fixture',concurrencySafe:false,inputSchema:{type:'object',properties:{}}}],hostModules:{model:{methods:['prepare','stream']},capability:{methods:['execute']},permission:{methods:['decide']}},messages:[{role:'user',content:[{type:'text',text:'use fixture tool'}]}]}});let streams=0;const held=[];for(let i=0;i<60;i++){const m=await read();if(m.kind==='request'){let p;if(m.module==='model'&&m.payload.operation==='prepare')p={prepared:{request:m.payload.request,provider:'host-provider',model:'host-model'}};else if(m.module==='model'&&m.payload.operation==='stream'){streams++;p={events:streams===1?[{type:'message_start',role:'assistant'},{type:'tool_call_start',id:'call1',name:'owned_tool'},{type:'tool_call_end',toolCall:{id:'call1',name:'owned_tool',input:{},raw:{}}},{type:'tool_call_start',id:'call2',name:'owned_tool'},{type:'tool_call_end',toolCall:{id:'call2',name:'owned_tool',input:{},raw:{}}},{type:'tool_call_start',id:'call3',name:'serial_tool'},{type:'tool_call_end',toolCall:{id:'call3',name:'serial_tool',input:{},raw:{}}},{type:'message_end',finishReason:'tool_calls'}]:[{type:'text_delta',text:'finished'},{type:'message_end',finishReason:'stop'}]};}else if(m.module==='permission')p={decision:{type:'allow'}};else if(m.module==='capability'){p={type:'success',toolCallId:m.payload.toolCallId,toolName:m.payload.name,content:[{type:'text',text:'done'}],startedAt:'2026-01-01T00:00:00.000Z',completedAt:'2026-01-01T00:00:00.000Z'};if(m.payload.name==='owned_tool'){held.push({m,p});if(held.length===2){for(const h of held.reverse())send({kind:'response',messageId:'held-'+h.m.payload.toolCallId,inReplyTo:h.m.messageId,requestId:h.m.requestId,ok:true,payload:h.p});}continue;}}else throw Error('unexpected '+JSON.stringify(m));send({kind:'response',messageId:`reply${i}`,inReplyTo:m.messageId,requestId:m.requestId,ok:true,payload:p});}else if(m.final)break;}}
catch(e){raw.push({probeError:String(e)})}finally{socket.destroy();child.kill('SIGTERM');await once(child,'exit');fs.writeFileSync(path.join(out,'result.json'),JSON.stringify({side,entry,raw,stderr},null,2));}
